using Notifications.Legacy;

namespace Notifications;

/// <summary>Sends email messages.</summary>
public sealed class EmailClient
{
    public bool SendEmail(Message message)
    {
        var mailMessage = new MailMessage
        {
            To = message.Recipient.EmailAddress,
            Subject = message.Subject,
            Body = message.Body,
        };

        return MailApiV2.Send(mailMessage) && mailMessage.Body.Length > 0;
    }
}
